{"component": {"id": 29885, "componentId": 16146, "authorUserId": "user_38qAOtph5HovpSn2yjNYXjbTOm2", "name": "Focus Frame Border", "demoName": "Default", "description": "A wrapper that adds a camera-style focus-lock border to any card or panel, using four pulsing glowing corner brackets instead of a continuous shine ring.", "previewUrl": "https://cdn.21st.dev/shadcnspace/shine-border-06/default/preview.1790133202193-ab524238-42dc-495a-877b-e5fdd3cb03de.png", "installCommand": "npx shadcn@latest add "https://21st.dev/r/shadcnspace/shine-border-06?api_key=$API_KEY_21ST"", "componentCode": "import React, { ReactNode } from "react";
import { cn } from "@/lib/utils";

type FocusFrameBorderProps = {
  children: ReactNode;
  className?: string;
  duration?: number;
  color?: string;
};

const corners = [
  {
    position: "top-0 left-0",
    edges: "border-t-1 border-l-1 rounded-tl-xl",
    delay: 0,
  },
  {
    position: "top-0 right-0",
    edges: "border-t-1 border-r-1 rounded-tr-xl",
    delay: 0.3,
  },
  {
    position: "bottom-0 left-0",
    edges: "border-b-1 border-l-1 rounded-bl-xl",
    delay: 0.6,
  },
  {
    position: "bottom-0 right-0",
    edges: "border-b-1 border-r-1 rounded-br-xl",
    delay: 0.9,
  },
];

const FocusFrameBorder = ({
  children,
  className,
  duration = 2.4,
  color = "var(--color-blue-500)",
}: FocusFrameBorderProps) => {
  return (
    <>
      <style>{`
        @keyframes focus-pulse {
          0%, 100% { opacity: 0.6; }
          50% { opacity: 1; }
        }
        .animate-focus-pulse {
          animation: focus-pulse var(--duration, 2.4s) ease-in-out infinite;
        }
      `}</style>
      <div className={cn("relative rounded-2xl", className)}>
        {/* Pulsing corner brackets */}
        {corners.map((corner) => (
          <div
            key={corner.position}
            className={cn(
              "absolute z-20 size-10 pointer-events-none animate-focus-pulse",
              corner.position,
              corner.edges,
            )}
            style={
              {
                borderColor: color,
                filter: `drop-shadow(0 0 6px ${color}) drop-shadow(0 0 12px ${color})`,
                animationDelay: `${corner.delay}s`,
                "--duration": `${duration}s`,
              } as React.CSSProperties
            }
          />
        ))}

        {/* Content Layer */}
        <div className="relative z-10 rounded-xl bg-card border border-border/80 overflow-hidden h-full">
          {children}
        </div>
      </div>
    </>
  );
};

export default FocusFrameBorder;
